-- Run once in the Supabase SQL Editor for project szrrdgiivhfhvugemvfu.
begin;

create table public.asgc_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.asgc_admins enable row level security;
create policy "Admins see their membership" on public.asgc_admins for select to authenticated using (user_id = (select auth.uid()));
revoke all on public.asgc_admins from anon, authenticated;
grant select on public.asgc_admins to authenticated;

create function public.asgc_is_admin() returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.asgc_admins where user_id = auth.uid());
$$;
revoke all on function public.asgc_is_admin() from public;
grant execute on function public.asgc_is_admin() to anon, authenticated;

create table public.asgc_content (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('news','publication','photo','video','press','speech','coverage')),
  slug text not null check (length(slug) between 1 and 200),
  title text not null check (length(title) between 1 and 500),
  status text not null default 'draft' check (status in ('draft','published','archived')),
  data jsonb not null default '{}' check (jsonb_typeof(data) = 'object' and octet_length(data::text) <= 200000),
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  unique(kind,slug)
);
alter table public.asgc_content enable row level security;
create policy "Public reads published content" on public.asgc_content for select to anon, authenticated using (status = 'published' or public.asgc_is_admin());
create policy "Admins insert content" on public.asgc_content for insert to authenticated with check (public.asgc_is_admin());
create policy "Admins update content" on public.asgc_content for update to authenticated using (public.asgc_is_admin()) with check (public.asgc_is_admin());
create policy "Admins delete content" on public.asgc_content for delete to authenticated using (public.asgc_is_admin());
revoke all on public.asgc_content from anon, authenticated;
grant select on public.asgc_content to anon;
grant select, insert, update, delete on public.asgc_content to authenticated;

create function public.asgc_submission_strings(value jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select not exists (
    select 1 from jsonb_each(value) as fields where jsonb_typeof(fields.value) <> 'string'
  );
$$;

create table public.asgc_submissions (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('contact','partnership','newsletter')),
  data jsonb not null check (jsonb_typeof(data) = 'object' and public.asgc_submission_strings(data) and data ? 'email' and jsonb_typeof(data->'email') = 'string' and octet_length(data::text) <= 20000 and length(data->>'email') between 3 and 320 and data->>'email' like '%@%'),
  status text not null default 'unread' check (status in ('unread','read','archived','confirmed','cancelled','active','unsubscribed')),
  created_at timestamptz not null default now()
);
alter table public.asgc_submissions enable row level security;
create policy "Visitors submit forms" on public.asgc_submissions for insert to anon, authenticated with check (status = 'unread');
create policy "Only admins read submissions" on public.asgc_submissions for select to authenticated using (public.asgc_is_admin());
create policy "Only admins update submissions" on public.asgc_submissions for update to authenticated using (public.asgc_is_admin()) with check (public.asgc_is_admin());
create policy "Only admins delete submissions" on public.asgc_submissions for delete to authenticated using (public.asgc_is_admin());
revoke all on public.asgc_submissions from anon, authenticated;
grant insert(kind,data) on public.asgc_submissions to anon;
grant select, insert, update, delete on public.asgc_submissions to authenticated;

-- Published website assets; uploads and deletions require an approved admin account.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('asgc-assets','asgc-assets',true,10485760,array['image/png','image/jpeg','image/webp','application/pdf']) on conflict (id) do nothing;
create policy "ASGC admins upload assets" on storage.objects for insert to authenticated with check (bucket_id = 'asgc-assets' and public.asgc_is_admin());
create policy "ASGC admins manage assets" on storage.objects for select to authenticated using (bucket_id = 'asgc-assets' and public.asgc_is_admin());
create policy "ASGC admins delete assets" on storage.objects for delete to authenticated using (bucket_id = 'asgc-assets' and public.asgc_is_admin());

-- Realtime notifications are filtered by the same row-level permissions.
alter publication supabase_realtime add table public.asgc_content, public.asgc_submissions;
commit;

-- Existing public website content; rerunning preserves admin edits.
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('news','nigeria-africa-trade-corridors','ASGC Convenes High-Level Dialogue on Nigeria–Africa Trade Corridors','published','{"slug":"nigeria-africa-trade-corridors","title":"ASGC Convenes High-Level Dialogue on Nigeria–Africa Trade Corridors","category":"Diplomacy","date":"September 15, 2026","author":"ASGC Communications","featured":true,"img":"https://images.unsplash.com/photo-1739285452644-3a2c009112fe?w=900&h=500&fit=crop&auto=format","excerpt":"The Centre brought together senior officials, business leaders and scholars to examine new frameworks for intra-African trade facilitation and sustainable economic corridors across the continent.","sections":[{"heading":"Connecting markets through dialogue","paragraphs":["Trade corridors are more than transport routes. They connect producers, logistics providers, public institutions and consumers across borders. The dialogue described in this story places those relationships at the centre of a wider conversation about economic cooperation.","For businesses, a dependable corridor means being able to plan a shipment, understand the required documentation and reach buyers with confidence. Bringing policy and commercial perspectives together helps identify where those expectations meet practical obstacles."],"id":"section-1"},{"heading":"From infrastructure to everyday access","paragraphs":["Physical infrastructure is only one part of the picture. Clear information, consistent border procedures and coordination between institutions also shape the experience of trading across markets. Smaller enterprises need these systems to be understandable and accessible.","A useful framework considers the entire journey of a product: production, certification, transport, border clearance and delivery. Looking at the journey as a whole can reveal barriers that would otherwise remain hidden between institutional responsibilities."],"id":"section-2"},{"heading":"Keeping cooperation practical","paragraphs":["Dialogue creates the most value when it helps different participants understand a shared problem. Public institutions can explain policy objectives, businesses can describe operational constraints, and researchers can identify questions that require further evidence.","ASGC’s wider mandate connects diplomacy with inclusive trade and responsible investment. Readers interested in these themes can explore the Centre’s programme areas or contact the team about opportunities for engagement."],"id":"section-3"}],"readingMinutes":2}',0) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('news','responsible-investment-west-africa','ASGC Publishes New Policy Brief on Responsible Investment Frameworks for West Africa','published','{"slug":"responsible-investment-west-africa","title":"ASGC Publishes New Policy Brief on Responsible Investment Frameworks for West Africa","category":"Policy","date":"August 28, 2026","author":"ASGC Research Unit","featured":false,"img":"https://images.unsplash.com/photo-1590274853856-f22d5ee3d228?w=600&h=400&fit=crop&auto=format","excerpt":"A new ASGC research brief examines ethical investment standards and their application across the West African economic landscape.","sections":[{"heading":"Investment with a wider purpose","paragraphs":["Responsible investment asks how capital can support economic activity while taking account of people, communities and the environment. The policy theme introduced in this brief is relevant to both those seeking investment and those deciding where to allocate it.","The discussion extends beyond the size of a financial commitment. It considers how a project is governed, how local stakeholders are heard and how its intended benefits can be assessed over time."],"id":"section-1"},{"heading":"Questions for institutions and investors","paragraphs":["A practical assessment begins with clear questions. What development need does a project address? Who may be affected by its activities? What information will be available to communities, and how will concerns be raised and considered?","Employment, environmental responsibility and transparency are useful areas for dialogue. Defining expectations early gives project partners a clearer basis for discussing responsibilities throughout the life of an investment."],"id":"section-2"},{"heading":"Building a shared understanding","paragraphs":["Investors, public institutions and community organisations bring different perspectives to the same project. Research and policy dialogue can help make those perspectives visible and identify where further consultation is needed.","Explore the Publications & Research section for the site’s publication catalogue. For enquiries about this sample brief or ASGC’s research themes, contact the Centre directly."],"id":"section-3"}],"readingMinutes":2}',1) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('news','economic-diplomacy-training','ASGC Launches Economic Diplomacy Training Programme for Young Professionals','published','{"slug":"economic-diplomacy-training","title":"ASGC Launches Economic Diplomacy Training Programme for Young Professionals","category":"ASGC News","date":"July 14, 2026","author":"ASGC Communications","featured":false,"img":"https://images.unsplash.com/photo-1739298061740-5ed03045b280?w=600&h=400&fit=crop&auto=format","excerpt":"Twenty-five emerging leaders from across Nigeria participated in the inaugural ASGC Economic Diplomacy Intensive, gaining skills in negotiation and international engagement.","sections":[{"heading":"Preparing a new generation","paragraphs":["Economic diplomacy brings international engagement into conversation with trade, investment and development. For emerging professionals, understanding these connections offers a foundation for working across institutions, sectors and national boundaries.","The programme introduced in this story reflects ASGC’s focus on skills and leadership. Its themes connect professional development with the practical challenge of communicating clearly and building productive relationships."],"id":"section-1"},{"heading":"Learning through practical questions","paragraphs":["Negotiation begins with preparation: understanding the issue, identifying interests and recognising the constraints facing others. A useful learning exercise asks participants to consider how different parties might work towards a shared outcome.","International engagement also requires careful listening and an ability to explain complex ideas to varied audiences. Research, written communication and reflection on different perspectives complement the interpersonal side of diplomatic work."],"id":"section-2"},{"heading":"Continuing the learning journey","paragraphs":["Professional development is an ongoing process. Mentorship and exchange can help emerging leaders connect classroom ideas with the decisions they encounter in their work.","Readers can visit the Programmes section to explore ASGC’s skills and leadership focus. Contact the Centre for confirmed information about participation, schedules and future opportunities."],"id":"section-3"}],"readingMinutes":1}',2) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('news','afcfta-inclusive-african-trade','Commentary: AfCFTA and the Path to Inclusive African Trade','published','{"slug":"afcfta-inclusive-african-trade","title":"Commentary: AfCFTA and the Path to Inclusive African Trade","category":"Commentary","date":"June 5, 2026","author":"ASGC Policy Team","featured":false,"img":"https://images.unsplash.com/photo-1739298061707-cefee19941b7?w=600&h=400&fit=crop&auto=format","excerpt":"The African Continental Free Trade Area holds significant promise, but realising its benefits requires sustained investment in trade facilitation, capacity building and institutional reform.","sections":[{"heading":"Looking beyond market access","paragraphs":["Inclusive trade is concerned with who can participate in economic opportunity. This commentary considers the practical conditions that allow smaller enterprises to engage with markets beyond their immediate surroundings.","A discussion of continental trade should therefore include the experience of the entrepreneur preparing a first cross-border sale. Information, business capabilities and reliable connections matter alongside the broader ambition of integration."],"id":"section-1"},{"heading":"Making participation possible","paragraphs":["Businesses need understandable guidance on product requirements, logistics and the steps involved in reaching new buyers. The challenge is to turn complex processes into information that can support everyday decisions.","Capacity building can provide space to examine these questions. Dialogue between business organisations, researchers and public institutions can also help identify where existing support falls short of what enterprises need."],"id":"section-2"},{"heading":"An agenda for sustained dialogue","paragraphs":["Inclusive outcomes require attention to different starting points. The needs of a young entrepreneur, an established manufacturer and a small agricultural business will not always be the same.","This perspective supports a continuing conversation about trade facilitation and skills. ASGC’s programme themes offer a starting point for readers interested in connecting policy discussion with practical participation."],"id":"section-3"}],"readingMinutes":1}',3) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('news','nigeria-gulf-cooperation-forum','Nigeria–Gulf Cooperation Forum: Building New Economic Bridges','published','{"slug":"nigeria-gulf-cooperation-forum","title":"Nigeria–Gulf Cooperation Forum: Building New Economic Bridges","category":"International Cooperation","date":"May 20, 2026","author":"ASGC Communications","featured":false,"img":"https://images.unsplash.com/photo-1633095975779-fd354aa0dc95?w=600&h=400&fit=crop&auto=format","excerpt":"ASGC supported a dialogue between Nigerian government officials and Gulf Cooperation Council partners, exploring new frameworks for trade, investment and cultural exchange.","sections":[{"heading":"A platform for economic exchange","paragraphs":["International cooperation develops through relationships as well as formal frameworks. The forum introduced in this story brings attention to the role of dialogue in understanding economic priorities across regions.","For Nigerian and Gulf partners, a useful conversation begins by listening to the objectives of participating institutions and businesses. Shared understanding can help participants identify subjects that deserve closer exploration."],"id":"section-1"},{"heading":"Connecting commercial and cultural perspectives","paragraphs":["Trade and investment discussions benefit from a wider appreciation of institutional context and professional practice. Cultural exchange can support the relationships on which sustained engagement depends.","An exploratory forum offers a setting for questions about market needs, partnership expectations and responsible investment. It is also a place to distinguish promising ideas from proposals that require additional research and consultation."],"id":"section-2"},{"heading":"Developing relationships over time","paragraphs":["A meeting is a starting point for cooperation. Continued communication and a clear understanding of each participant’s responsibilities help turn initial interest into a more informed discussion.","ASGC’s partnerships and events pages introduce related areas of work. Readers seeking confirmed details about participation or institutional collaboration can contact the Centre through the website."],"id":"section-3"}],"readingMinutes":1}',4) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('publication','responsible-investment-in-west-africa-principles-frameworks-and-opportunities','Responsible Investment in West Africa: Principles, Frameworks and Opportunities','published','{"title":"Responsible Investment in West Africa: Principles, Frameworks and Opportunities","type":"Policy Brief","year":"2026","author":"ASGC Research Unit","date":"August 2026","summary":"An examination of responsible investment standards and their application across the West African economic landscape, with recommendations for policy and practice.","pages":"22 pages","img":"https://images.unsplash.com/photo-1590274853856-f22d5ee3d228?w=400&h=550&fit=crop&auto=format"}',0) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('publication','afcfta-and-the-path-to-inclusive-african-trade-policy-perspectives-for-nigeria','AfCFTA and the Path to Inclusive African Trade: Policy Perspectives for Nigeria','published','{"title":"AfCFTA and the Path to Inclusive African Trade: Policy Perspectives for Nigeria","type":"Policy Brief","year":"2026","author":"ASGC Policy Team","date":"June 2026","summary":"This brief analyses the implications of the African Continental Free Trade Area for Nigerian exporters, SMEs and policymakers, identifying opportunities and structural barriers.","pages":"18 pages","img":"https://images.unsplash.com/photo-1739298061740-5ed03045b280?w=400&h=550&fit=crop&auto=format"}',1) on conflict (kind,slug) do nothing;
insert into public.asgc_content (kind,slug,title,status,data,sort_order) values ('publication','economic-diplomacy-and-the-role-of-nigerian-missions-abroad','Economic Diplomacy and the Role of Nigerian Missions Abroad','published','{"title":"Economic Diplomacy and the Role of Nigerian Missions Abroad","type":"Research Paper","year":"2026","author":"Ambassador Ahmed Sule","date":"April 2026","summary":"A practitioner''s analysis of how Nigerian diplomatic missions can be more effectively structured to advance economic diplomacy, trade promotion and investment attraction.","pages":"34 pages","img":"https://images.unsplash.com/photo-1739285452644-3a2c009112fe?w=400&h=550&fit=crop&auto=format"}',2) on conflict (kind,slug) do nothing;
